const EmployeePage = () => {
  const { id } = useParams();
  const [employeeName, setEmployeeName] = useState("");
  const [employeePhone, setEmployeePhone] = useState("");
  const [employeeRole, setEmployeeRole] = useState("driver");
  const [employeeSalary, setEmployeeSalary] = useState("");
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [isFormVisible, setFormVisible] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [salaryDetails, setSalaryDetails] = useState({
    startDate: "",
    endDate: "",
    expense: "",
    daysWorked: 0,
  });
  const [detailsTable, setDetailsTable] = useState([]);

  const fetchEmployeesByRole = useCallback(async (role) => {
    try {
      const response = await axios.get(
        `http://localhost:5001/api/employee/employeesByRole/${id}/${role}`
      );
      setFilteredEmployees(response.data);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  }, [id]);

  const handleEmployeeClick = async (phone) => {
    try {
      const response = await axios.get(`http://localhost:5001/api/employee/${phone}`);
      setSelectedEmployee(response.data);
    } catch (error) {
      console.error("Error fetching employee details:", error);
      alert("Error fetching employee details");
    }
  };

  const addEmployee = async () => {
    try {
      const newEmployee = {
        name: employeeName,
        phone: employeePhone,
        role: employeeRole,
        fixed_salary: employeeSalary,
        lorry_id: id,
      };
      await axios.post("http://localhost:5001/api/employee/add", newEmployee);
      alert("Employee added successfully");
      fetchEmployeesByRole(employeeRole);
      setFormVisible(false);
    } catch (error) {
      console.error("Error adding employee:", error);
      alert("Error adding employee");
    }
  };

  const handleDeleteEmployee = async (phone) => {
    try {
      const response = await axios.delete(`http://localhost:5001/api/employee/${phone}`);
      alert("Employee deleted successfully");
      fetchEmployeesByRole(employeeRole); // Refresh the list
      setSelectedEmployee(null); // Deselect the employee
    } catch (error) {
      console.error("Error deleting employee:", error);
      if (error.response && error.response.status === 404) {
        alert("Employee not found");
      } else {
        alert("Error deleting employee");
      }
    }
  };

  const handleDateChange = () => {
    const startDate = new Date(salaryDetails.startDate);
    const endDate = new Date(salaryDetails.endDate);
    const timeDiff = Math.abs(endDate - startDate);
    const daysWorked = Math.ceil(timeDiff / (1000 * 3600 * 24)) + 1; // +1 to include the start date
    setSalaryDetails((prevDetails) => ({
      ...prevDetails,
      daysWorked,
    }));
  };

  const handleUpdateSalary = async () => {
    if (!selectedEmployee) {
      alert("Please select an employee first");
      return;
    }

    try {
      const { startDate, endDate, expense, daysWorked } = salaryDetails;
      await axios.put(`http://localhost:5001/api/employee/updateSalary/${selectedEmployee.phone}`, {
        startDate,
        endDate,
        expense,
        daysWorked,
      });
      alert("Salary details updated successfully");
      // Refresh employee details
      handleEmployeeClick(selectedEmployee.phone);
    } catch (error) {
      console.error("Error updating salary details:", error);
      alert("Error updating salary details");
    }
  };

  const handleViewDetails = async (phone) => {
    try {
      const response = await axios.get(`http://localhost:5001/api/salary/salaryDetails/${phone}`);
      setDetailsTable(response.data);
    } catch (error) {
      console.error('Error fetching salary details:', error);
      alert('Error fetching salary details');
    }
  };

  useEffect(() => {
    fetchEmployeesByRole(employeeRole);
  }, [employeeRole, id, fetchEmployeesByRole]);

  const handleRoleChange = (role) => {
    setEmployeeRole(role);
    fetchEmployeesByRole(role);
  };

  return (
    <Container>
      <Header>
        <LorryTitle>Lorry {id}</LorryTitle>
      </Header>

      <Button onClick={() => setFormVisible(true)}>Add Employee</Button>

      {isFormVisible && (
        <Form>
          <Input
            type="text"
            placeholder="Employee Name"
            value={employeeName}
            onChange={(e) => setEmployeeName(e.target.value)}
          />
          <Input
            type="text"
            placeholder="Phone Number"
            value={employeePhone}
            onChange={(e) => setEmployeePhone(e.target.value)}
          />
          <Select
            value={employeeRole}
            onChange={(e) => setEmployeeRole(e.target.value)}
          >
            <option value="driver">Driver</option>
            <option value="driller">Driller</option>
            <option value="manager">Manager</option>
            <option value="worker">Worker</option>
          </Select>
          <Input
            type="number"
            placeholder="Fixed Salary"
            value={employeeSalary}
            onChange={(e) => setEmployeeSalary(e.target.value)}
          />
          <Button onClick={addEmployee}>Add Employee</Button>
          <Button onClick={() => setFormVisible(false)}>Cancel</Button>
        </Form>
      )}

      <EmployeeRoles>
        <RoleTabs>
          <Tab onClick={() => handleRoleChange("driver")}>Drivers</Tab>
          <Tab onClick={() => handleRoleChange("driller")}>Drillers</Tab>
          <Tab onClick={() => handleRoleChange("manager")}>Managers</Tab>
          <Tab onClick={() => handleRoleChange("worker")}>Workers</Tab>
        </RoleTabs>

        <EmployeeList>
          {filteredEmployees.length > 0 ? (
            filteredEmployees.map((employee) => (
              <EmployeeItem key={employee.phone}>
                <div onClick={() => handleEmployeeClick(employee.phone)}>
                  {employee.name} ({employee.phone})
                </div>
                <Button onClick={() => handleViewDetails(employee.phone)}>
                  Details
                </Button>
                <Button onClick={() => setFormVisible(true)}>Update</Button>
                <Button onClick={() => handleDeleteEmployee(employee.phone)}>
                  Delete
                </Button>
              </EmployeeItem>
            ))
          ) : (
            <EmployeeItem>No employees found for this role.</EmployeeItem>
          )}
        </EmployeeList>
      </EmployeeRoles>

      {selectedEmployee && (
        <Form>
          <Input
            type="text"
            value={selectedEmployee.phone}
            readOnly
            placeholder="Phone Number"
          />
          <Input
            type="date"
            placeholder="Start Date"
            value={salaryDetails.startDate}
            onChange={(e) => {
              setSalaryDetails({ ...salaryDetails, startDate: e.target.value });
              handleDateChange();
            }}
          />
          <Input
            type="date"
            placeholder="End Date"
            value={salaryDetails.endDate}
            onChange={(e) => {
              setSalaryDetails({ ...salaryDetails, endDate: e.target.value });
              handleDateChange();
            }}
          />
          <Input
            type="number"
            placeholder="Expense"
            value={salaryDetails.expense}
            onChange={(e) => setSalaryDetails({ ...salaryDetails, expense: e.target.value })}
          />
          <Button onClick={handleUpdateSalary}>Update Salary</Button>
        </Form>
      )}

      {detailsTable.length > 0 && (
        <DetailsTable>
          <thead>
            <tr>
              <th>Name</th>
              <th>Phone</th>
              <th>Expense</th>
              <th>Date</th>
              <th>Days Worked</th>
            </tr>
          </thead>
          <tbody>
            {detailsTable.map((detail, index) => (
              <tr key={index}>
                <td>{detail.name}</td>
                <td>{detail.phone}</td>
                <td>{detail.expense}</td>
                <td>{detail.date}</td>
                <td>{detail.daysWorked}</td>
              </tr>
            ))}
          </tbody>
        </DetailsTable>
      )}
    </Container>
  );
};

